pub fn compare_iter<T, L, F, G, Skip, Cmp>(mut left: L, mut right: G, skip: Skip, cmp: Cmp) -> Ordering
where L: Iterator<Item = T>, G: Iterator<Item = T>, Skip: Fn(&T) -> bool, Cmp: Fn(&T, &T) -> Ordering {
    let mut left = left.filter(|x| !skip(x)).peekable();
    let mut right = right.filter(|x| !skip(x)).peekable();
    loop {
        match (left.peek(), right.peek()) {
            (None, None) => return Ordering::Equal,
            (None, Some(_)) => return Ordering::Less,
            (Some(_), None) => return Ordering::Greater,
            (Some(l), Some(r)) if l.is_digit(10) && r.is_digit(10) => {
                let mut l_zeros = 0;
                let mut r_zeros = 0;
                while left.peek().map_or(false, |x| x.is_digit(10) && *x == '0') { left.next(); l_zeros += 1; }
                while right.peek().map_or(false, |x| x.is_digit(10) && *x == '0') { right.next(); r_zeros += 1; }
                // Now both have non-zero digits (or are exhausted)
                loop {
                    match (left.peek(), right.peek()) {
                        (Some(l), Some(r)) if l.is_digit(10) && r.is_digit(10) => {
                            let ord = cmp(l, r);
                            if ord != Ordering::Equal { return ord; }
                            left.next(); right.next();
                        }
                        (Some(l), None) => return Ordering::Greater,  // left has more digits
                        (None, Some(r)) => return Ordering::Less,
                        _ => break,
                    }
                }
                // Hmm, and then what about l_zeros vs r_zeros?
            }
        }
    }
}
```

