fn natural_cmp(a: &str, b: &str) -> Ordering {
    let mut ai = a.chars().filter(|c| !c.is_whitespace());
    let mut bi = b.chars().filter(|c| !c.is_whitespace());
    loop {
        match (ai.next(), bi.next()) {
            (None, None) => return Equal,
            (None, Some(_)) => return Less,
            (Some(_), None) => return Greater,
            (Some(l), Some(r)) => {
                if l.is_ascii_digit() && r.is_ascii_digit() {
                    // extract the digit runs
                    let la = collect_digits(&mut ai, l);
                    let rb = collect_digits(&mut bi, r);
                    // compare
                    let ord = if la.starts_with('0') || rb.starts_with('0') {
                        la.cmp(&rb)   // byte-wise
                    } else {
                        numeric_cmp(&la, &rb)
                    };
                    if ord != Equal { return ord }
                    // equal → continue with the next chars
                } else {
                    match l.cmp(&r) { Equal => continue, o => return o }
                }
            }
        }
    }
}
```
