#[derive(Debug, Clone)]
pub enum GroupRef {
    /// `{}` - auto incrementing index, starting at 1
    Auto,
    /// `{N}` - explicit group index
    Index(usize),
    /// `{...}` - index could not be parsed, group is missing
    Missing,
}

#[derive(Debug, Clone)]
pub enum Part {
    Literal(String),
    Group(GroupRef, Option<usize>),
}

pub const ERR_OPEN: &str = "all opened placeholders must be closed by '}'";
pub const ERR_CLOSE: &str = "an unopened placeholder could not be closed by '}'";

pub fn parse(src: &str) -> Result<Vec<Part>, String> {
    let bytes = src.as_bytes();
    let mut i = 0usize;
    let mut out: Vec<Part> = Vec::new();
    let mut lit = String::new();

    macro_rules! flush {
        () => {
            if !lit.is_empty() {
                out.push(Part::Literal(std::mem::take(&mut lit)));
            }
        };
    }

    while i < bytes.len() {
        let c = src[i..].chars().next().unwrap();
        if c == '\\' {
            let esc_pos = i + 1;
            if esc_pos >= bytes.len() {
                // dangling escape character is silently dropped
                i = bytes.len();
                continue;
            }
            let nc = src[esc_pos..].chars().next().unwrap();
            match nc {
                '{' | '}' | '\\' => {
                    lit.push(nc);
                    i = esc_pos + nc.len_utf8();
                }
                _ => {
                    return Err(format!(
                        "invalid escape character of '{}' at '{}'",
                        nc, esc_pos
                    ))
                }
            }
        } else if c == '{' {
            flush!();
            i += 1;
            let mut content = String::new();
            let mut closed = false;
            while i < bytes.len() {
                let ch = src[i..].chars().next().unwrap();
                if ch == '\\' {
                    let esc_pos = i + 1;
                    if esc_pos >= bytes.len() {
                        i = bytes.len();
                        continue;
                    }
                    let nc = src[esc_pos..].chars().next().unwrap();
                    match nc {
                        '{' | '}' | '\\' => {
                            content.push(nc);
                            i = esc_pos + nc.len_utf8();
                        }
                        _ => {
                            return Err(format!(
                                "invalid escape character of '{}' at '{}'",
                                nc, esc_pos
                            ))
                        }
                    }
                } else if ch == '}' {
                    i += 1;
                    closed = true;
                    break;
                } else {
                    content.push(ch);
                    i += ch.len_utf8();
                }
            }
            if !closed {
                return Err(ERR_OPEN.to_string());
            }
            let (group_str, pad_str) = match content.find(':') {
                Some(p) => (&content[..p], &content[p + 1..]),
                None => (content.as_str(), ""),
            };
            let padding = if pad_str.is_empty() {
                None
            } else {
                match pad_str.parse::<usize>() {
                    Ok(p) => Some(p),
                    Err(_) => return Err(format!("unable to parse padding of '{}'", pad_str)),
                }
            };
            let group = if group_str.is_empty() {
                GroupRef::Auto
            } else {
                match group_str.parse::<usize>() {
                    Ok(n) => GroupRef::Index(n),
                    Err(_) => GroupRef::Missing,
                }
            };
            out.push(Part::Group(group, padding));
        } else if c == '}' {
            flush!();
            return Err(ERR_CLOSE.to_string());
        } else {
            lit.push(c);
            i += c.len_utf8();
        }
    }
    flush!();
    Ok(out)
}

/// Values the placeholders may refer to.
pub struct Captures<'a> {
    values: Vec<Option<&'a str>>,
}

impl<'a> Captures<'a> {
    pub fn new() -> Self {
        Captures { values: Vec::new() }
    }

    pub fn push(&mut self, value: Option<&'a str>) {
        self.values.push(value);
    }

    pub fn get(&self, index: usize) -> Option<&'a str> {
        self.values.get(index).copied().flatten()
    }
}

impl<'a> Default for Captures<'a> {
    fn default() -> Self {
        Self::new()
    }
}

pub fn format(parts: &[Part], caps: &Captures) -> String {
    let mut auto_index = 1usize;
    let mut out = String::new();
    for part in parts {
        match part {
            Part::Literal(s) => out.push_str(s),
            Part::Group(GroupRef::Auto, padding) => {
                let value = caps.get(auto_index);
                auto_index += 1;
                out.push_str(&apply(value, *padding));
            }
            Part::Group(GroupRef::Index(n), padding) => {
                let value = caps.get(*n);
                out.push_str(&apply(value, *padding));
            }
            Part::Group(GroupRef::Missing, padding) => {
                out.push_str(&apply(None, *padding));
            }
        }
    }
    out
}

fn apply(value: Option<&str>, padding: Option<usize>) -> String {
    let v = value.unwrap_or("");
    match padding {
        None => v.to_string(),
        Some(p) => match v.parse::<usize>() {
            Ok(n) => format!("{:0width$}", n, width = p),
            Err(_) => v.to_string(),
        },
    }
}
