use unicode_width::UnicodeWidthStr;

/// Display width of a string, taking multi-line content into account.
pub fn display_width(s: &str) -> usize {
    s.split('\n').map(|l| l.width()).max().unwrap_or(0)
}

pub fn render(headers: [&str; 2], rows: &[(String, String)]) -> String {
    let cells: Vec<Vec<String>> = {
        let mut v = Vec::new();
        v.push(vec![headers[0].to_string(), headers[1].to_string()]);
        for r in rows {
            v.push(vec![r.0.clone(), r.1.clone()]);
        }
        v
    };

    let widths: [usize; 2] = [
        cells.iter().map(|r| display_width(&r[0])).max().unwrap_or(0),
        cells.iter().map(|r| display_width(&r[1])).max().unwrap_or(0),
    ];

    let mut out = String::new();
    let border = format!(
        "+{}+{}+\n",
        "-".repeat(widths[0] + 2),
        "-".repeat(widths[1] + 2)
    );
    out.push_str(&border);
    out.push_str(&render_row(&cells[0], &widths, &[], None));
    out.push_str(&border);
    for (idx, row) in cells.iter().enumerate().skip(1) {
        out.push_str(&render_row(row, &widths, &[], Some(idx - 1)));
    }
    out.push_str(&border);
    out
}

fn render_row(
    row: &[String; 2],
    widths: &[usize; 2],
    _cells: &[Vec<String>],
    row_index: Option<usize>,
) -> String {
    let _ = row_index;
    let lines: [Vec<&str>; 2] = [
        row[0].split('\n').collect(),
        row[1].split('\n').collect(),
    ];
    let count = lines[0].len().max(lines[1].len());
    let mut out = String::new();
    for i in 0..count {
        out.push('|');
        for col in 0..2 {
            let line = lines[col].get(i).copied().unwrap_or("");
            let pad = widths[col].saturating_sub(line.width());
            out.push(' ');
            out.push_str(line);
            for _ in 0..pad {
                out.push(' ');
            }
            out.push_str(" |");
        }
        out.push('\n');
    }
    out
}
