fn walk(dir: &Path, rel: &Path, level: usize, min: usize, max: usize, out: &mut Vec<(PathBuf, usize)>) {
    let rd = match fs::read_dir(dir) { Ok(r) => r, Err(_) => return };
    for entry in rd {
        let entry = match entry { Ok(e) => e, Err(_) => continue };
        let path = entry.path();
        let child_rel = rel.join(entry.file_name());
        if level >= min && level <= max {
            out.push((child_rel.clone(), level));
        }
        let is_dir = entry.file_type().map(|t| t.is_dir()).unwrap_or(false);
        if is_dir && level < max {
            walk(&path, &child_rel, level + 1, min, max, out);
        }
    }
}
