use std::cmp::Ordering;

/// Natural ordering used by the `sort` option.
///
/// Whitespace characters are ignored while comparing and sequences of digits
/// are compared numerically. Sequences with a leading zero are compared as
/// plain strings instead.
pub fn natural_cmp(a: &str, b: &str) -> Ordering {
    let mut ai = a.chars().filter(|c| !c.is_whitespace()).peekable();
    let mut bi = b.chars().filter(|c| !c.is_whitespace()).peekable();

    loop {
        let l = ai.peek().copied();
        let r = bi.peek().copied();
        match (l, r) {
            (None, None) => return Ordering::Equal,
            (None, Some(_)) => return Ordering::Less,
            (Some(_), None) => return Ordering::Greater,
            (Some(l), Some(r)) => {
                if l.is_ascii_digit() && r.is_ascii_digit() {
                    let ls = take_digits(&mut ai);
                    let rs = take_digits(&mut bi);
                    let ord = if ls.starts_with('0') || rs.starts_with('0') {
                        ls.cmp(&rs)
                    } else {
                        numeric_cmp(&ls, &rs)
                    };
                    if ord != Ordering::Equal {
                        return ord;
                    }
                } else {
                    let ord = l.cmp(&r);
                    if ord != Ordering::Equal {
                        return ord;
                    }
                    ai.next();
                    bi.next();
                }
            }
        }
    }
}

fn take_digits<I: Iterator<Item = char>>(it: &mut std::iter::Peekable<I>) -> String {
    let mut out = String::new();
    while let Some(c) = it.peek().copied() {
        if c.is_ascii_digit() {
            out.push(c);
            it.next();
        } else {
            break;
        }
    }
    out
}

fn numeric_cmp(a: &str, b: &str) -> Ordering {
    a.len().cmp(&b.len()).then_with(|| a.cmp(b))
}
EOF
cat > src/table.rs <<'EOF'
use unicode_width::UnicodeWidthStr;

/// Display width of a string, taking multi-line content into account.
pub fn display_width(s: &str) -> usize {
    s.split('\n').map(|l| l.width()).max().unwrap_or(0)
}

pub fn render(headers: [&str; 2], rows: &[(String, String)]) -> String {
    let cells: Vec<Vec<String>> = {
        let mut v = Vec::new();
        v.push(vec![headers[0].to_string(), headers[1].to_string()]);
        for r in rows {
            v.push(vec![r.0.clone(), r.1.clone()]);
        }
        v
    };

    let widths: [usize; 2] = [
        cells.iter().map(|r| display_width(&r[0])).max().unwrap_or(0),
        cells.iter().map(|r| display_width(&r[1])).max().unwrap_or(0),
    ];

    let mut out = String::new();
    let border = format!(
        "+{}+{}+\n",
        "-".repeat(widths[0] + 2),
        "-".repeat(widths[1] + 2)
    );
    out.push_str(&border);
    out.push_str(&render_row(&cells[0], &widths, &[], None));
    out.push_str(&border);
    for (idx, row) in cells.iter().enumerate().skip(1) {
        out.push_str(&render_row(row, &widths, &[], Some(idx - 1)));
    }
    out.push_str(&border);
    out
}

fn render_row(
    row: &[String; 2],
    widths: &[usize; 2],
    _cells: &[Vec<String>],
    row_index: Option<usize>,
) -> String {
    let _ = row_index;
    let lines: [Vec<&str>; 2] = [
        row[0].split('\n').collect(),
        row[1].split('\n').collect(),
    ];
    let count = lines[0].len().max(lines[1].len());
    let mut out = String::new();
    for i in 0..count {
        out.push('|');
        for col in 0..2 {
            let line = lines[col].get(i).copied().unwrap_or("");
            let pad = widths[col].saturating_sub(line.width());
            out.push(' ');
            out.push_str(line);
            for _ in 0..pad {
                out.push(' ');
            }
            out.push_str(" |");
        }
        out.push('\n');
    }
    out
}
EOF
