        let rows: Vec<(String, String)> = result.iter().map(|(k, v)| (v.clone(), k.clone())).collect();
        let out = table::render(["Input", "Output"], &rows);
        let mut stdout = std::io::stdout();
        let _ = stdout.write_all(out.as_bytes());
        let _ = stdout.flush();
    }

    exit(if failed { 1 } else { 0 });
}

fn fail(style: &term::Style, message: &str) -> ! {
    term::print_error(style, message);
    exit(1);
}

fn missing_source_message(style: &term::Style) -> String {
    format!(
        "one of {}, {} or {} options must be set.\n{}: run '{} {}' for more information.",
        style.cyan("'regex', 'sort', 'map'"),
        style.cyan("'SOURCE'"),
        "",
        style.yellow_bold("usage"),
        style.cyan(&program_name()),
        style.cyan("--help"),
    )
}

fn program_name() -> String {
    env::args_os()
        .next()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_default()
}

fn extension(path: &Path) -> String {
    match path.extension() {
        Some(e) => format!(".{}", e.to_string_lossy()),
        None => String::new(),
    }
}

fn walk(dir: &Path, rel: &Path, level: usize, min: usize, max: usize, out: &mut Vec<PathBuf>) {
    let rd = match fs::read_dir(dir) {
        Ok(rd) => rd,
        Err(_) => return,
    };
    for entry in rd.flatten() {
        let child = rel.join(entry.file_name());
        if level >= min && level <= max {
            out.push(child.clone());
        }
        let is_dir = entry.file_type().map(|t| t.is_dir()).unwrap_or(false);
        if is_dir && level < max {
            walk(&entry.path(), &child, level + 1, min, max, out);
        }
    }
}

fn process(
    input: &str,
    mut output: String,
    cfg: &Config,
    result: &mut BTreeMap<String, String>,
    style: &term::Style,
) -> bool {
    if !cfg.overwrite {
        loop {
            let exists = Path::new(&output).exists();
            if !exists || output == input {
                break;
            }
            output = prepend_underscore(&output);
        }
    }
    if cfg.mkdir {
        if let Some(parent) = Path::new(&output).parent() {
            let _ = fs::create_dir_all(parent);
        }
    }
    if cfg.test {
        result.insert(output, input.to_string());
        return true;
    }
    match fs::rename(input, &output) {
        Ok(()) => {
            result.insert(output, input.to_string());
            true
        }
        Err(e) => {
            let label = style.red_bold("error");
            eprintln!("[{}] unable to rename '{}': {}", label, input, e);
            false
        }
    }
}

fn prepend_underscore(output: &str) -> String {
    let p = Path::new(output);
    let name = p
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default();
    let parent = p.parent().unwrap_or(Path::new(""));
    parent
        .join(format!("_{}", name))
        .to_string_lossy()
        .into_owned()
}
