#!/usr/bin/env python3
import os, shutil, subprocess

ORIG = "/workspace/executable"
MINE = "/tmp/nom/target/debug/nomino"
BASE = "/tmp/difftest"

def snapshot(root):
    out = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames.sort(); filenames.sort()
        rel = os.path.relpath(dirpath, root)
        for f in sorted(filenames):
            p = os.path.join(dirpath, f)
            try:
                data = open(p,'rb').read()
            except Exception as e:
                data = b'<err>'
            out.append((os.path.normpath(os.path.join(rel, f)), data))
        for d in sorted(dirnames):
            out.append((os.path.normpath(os.path.join(rel, d)) + '/', b''))
    return sorted(out)

def run_case(args, files=(), dirs=(), extra_files=None, links=(), mode="test"):
    results = []
    for name, exe in (("orig", ORIG), ("mine", MINE)):
        home = os.path.join(BASE, name)
        shutil.rmtree(home, ignore_errors=True)
        os.makedirs(home)
        root = os.path.join(home, "cwd")
        os.makedirs(root)
        os.symlink(exe, os.path.join(home, "exe"))
        for f in files:
            p = os.path.join(root, f)
            d = os.path.dirname(p)
            if d: os.makedirs(d, exist_ok=True)
            with open(p,'wb') as fh: fh.write(b"content:"+f.encode()+b"\n")
        for d in dirs:
            os.makedirs(os.path.join(root, d), exist_ok=True)
        if extra_files:
            for path, data in extra_files.items():
                p = os.path.join(root, path)
                d = os.path.dirname(p)
                if d: os.makedirs(d, exist_ok=True)
                with open(p,'wb') as fh: fh.write(data)
        if mode == "test":
            args = list(args) + ["-t"]
        r = subprocess.run(["./exe"]+args, cwd=root, capture_output=True)
        results.append((r.returncode, r.stdout, r.stderr, snapshot(root)))
    o, m = results
    problems = []
    if o[0] != m[0]: problems.append(f"rc: orig={o[0]} mine={m[0]}")
    if o[1] != m[1]: problems.append(f"stdout:\n--orig--\n{o[1].decode(errors='replace')}\n--mine--\n{m[1].decode(errors='replace')}")
    if o[2] != m[2]: problems.append(f"stderr:\n--orig--\n{o[2].decode(errors='replace')}\n--mine--\n{m[2].decode(errors='replace')}")
    if o[3] != m[3]:
        po = set(map(str,o[3])); pm = set(map(str,m[3]))
        problems.append("fs: only-orig=" + str(sorted(po-pm)) + " only-mine=" + str(sorted(pm-po)))
    return problems

def check(label, *a, **kw):
    p = run_case(*a, **kw)
    if p:
        print("FAIL", label)
        for x in p: print("   ", x)
        return False
    print("ok  ", label)
    return True

def check_real(label, *a, **kw):
    kw = dict(kw); kw["mode"] = "real"
    return check(label, *a, **kw)
