{"command": "cd /tmp/nom && cat > src/main.rs <<'RUSTEOF'
mod args;
mod pattern;
mod sortcmp;
mod table;
mod term;

use std::collections::{BTreeMap, HashMap};
use std::env;
use std::ffi::OsString;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::exit;

use regex::Regex;

#[derive(Clone, Copy, PartialEq)]
enum Mode {
    Regex,
    Sort,
    Map,
}

struct Config {
    test: bool,
    overwrite: bool,
    mkdir: bool,
    quiet: bool,
    no_extension: bool,
}

/// One rename operation: the source path (as found on disk) and the string used
/// for displaying it.
struct Entry {
    path: PathBuf,
    display: String,
}

fn main() {
    let matches = args::build_command().get_matches();
    let style = term::Style::new(term::stderr_is_terminal());

    if let Some(dir) = matches.get_one::<PathBuf>("dir") {
        if let Err(e) = env::set_current_dir(dir) {
            fail(&style, &e.to_string());
        }
    }

    let regex_arg: Option<&String> = matches.get_one("regex");
    let sort_arg: Option<&String> = matches.get_one("sort");
    let map_arg: Option<&PathBuf> = matches.get_one("map");
    let patterns: Vec<String> = matches
        .get_many::<String>("patterns")
        .map(|it| it.cloned().collect())
        .unwrap_or_default();

    let (mode, source): (Mode, Option<String>) = if regex_arg.is_some() {
        (Mode::Regex, None)
    } else if sort_arg.is_some() {
        (Mode::Sort, None)
    } else if map_arg.is_some() {
        (Mode::Map, None)
    } else if patterns.len() >= 2 {
        (Mode::Regex, Some(patterns[patterns.len() - 2].clone()))
    } else {
        fail(&style, &missing_source_message(&style));
    };

    let cfg = Config {
        test: matches.get_flag("test"),
        overwrite: matches.get_flag("overwrite"),
        mkdir: matches.get_flag("mkdir"),
        quiet: matches.get_flag("quiet"),
        no_extension: matches.get_flag("no-extension"),
    };

    let generate: Option<&PathBuf> = matches.get_one("generate");
    let output_pattern: Option<&String> = patterns.last();

    // The regular expression is compiled before the output pattern is validated.
    let regex: Option<Regex> = match mode {
        Mode::Regex => {
            let src = regex_arg
                .map(|s| s.as_str())
                .or_else(|| source.as_deref())
                .unwrap_or_default();
            Some(Regex::new(src).unwrap_or_else(|e| fail(&style, &e.to_string())))
        }
        _ => None,
    };

    // The map file is only read when the map mode is selected.
    let mut map_entries: Vec<(String, String)> = Vec::new();
    if mode == Mode::Map {
        let path = map_arg.unwrap();
        let content = fs::read_to_string(path).unwrap_or_else(|e| fail(&style, &e.to_string()));
        let parsed: HashMap<String, String> =
            serde_json::from_str(&content).unwrap_or_else(|e| fail(&style, &e.to_string()));
        map_entries = parsed.into_iter().collect();
    }

    // The output pattern is required by the sort mode only.
    let output = match output_pattern {
        Some(p) => p.clone(),
        None => {
            if mode == Mode::Sort {
                fail(&style, "[output-format] output formatter must be set");
            }
            String::new()
        }
    };

    let parts = pattern::parse(&output)
        .unwrap_or_else(|e| fail(&style, &format!("[output-format] {}", e)));

    let mut result: BTreeMap<String, String> = BTreeMap::new();
    let mut failed = false;

    let entries: Vec<Entry> = match mode {
        Mode::Regex => {
            let depth_arg: Option<usize> = matches.get_one("depth").copied();
            let max_depth_arg: Option<usize> = matches.get_one("max-depth").copied();
            let pattern_src = regex_arg
                .map(|s| s.as_str())
                .or_else(|| source.as_deref())
                .unwrap_or_default();
            let inferred = pattern_src.matches('/').count() + 1;
            let depth = depth_arg.unwrap_or(inferred);
            let max_depth = max_depth_arg.unwrap_or(depth);
            let min_depth = depth.min(max_depth);

            let mut paths: Vec<PathBuf> = Vec::new();
            walk(
                Path::new("."),
                Path::new(""),
                0,
                min_depth,
                max_depth,
                &mut paths,
            );

            let re = regex.unwrap();
            let mut entries = Vec::new();
            for path in paths {
                let name = path.to_string_lossy().into_owned();
                let caps = match re.captures(&name) {
                    Some(c) => c,
                    None => continue,
                };
                let mut values = pattern::Captures::new();
                for i in 0..caps.len() {
                    values.push(caps.get(i).map(|m| m.as_str().to_string()));
                }
                for (i, cname) in re.capture_names().enumerate() {
                    if let Some(n) = cname {
                        values.add_name(&n, i);
                    }
                }
                let ext = if cfg.no_extension {
                    String::new()
                } else {
                    extension(&path)
                };
                let out = pattern::format(&parts, &values) + &ext;
                entries.push(Entry {
                    path,
                    display: name,
                    output: Some(out),
                });
            }
            entries
        }
        Mode::Sort => {
            let mut list: Vec<(OsString, String)> = match fs::read_dir(".") {
                Ok(rd) => rd
                    .flatten()
                    .map(|e| {
                        let os = e.file_name();
                        let disp = os.to_string_lossy().into_owned();
                        (os, disp)
                    })
                    .collect(),
                Err(_) => Vec::new(),
            };
            list.sort_by(|a, b| sortcmp::natural_cmp(&a.1, &b.1));
            let desc = sort_arg.map(|s| s.as_str()) == Some("desc");
            if desc {
                list.reverse();
            }
            let mut entries = Vec::new();
            for (idx, (os, name)) in list.into_iter().enumerate() {
                let mut values = pattern::Captures::new();
                values.push(Some(name.clone()));
                values.push(Some((idx + 1).to_string()));
                let path = PathBuf::from(os);
                let ext = if cfg.no_extension {
                    String::new()
                } else {
                    extension(&path)
                };
                let out = pattern::format(&parts, &values) + &ext;
                entries.push(Entry {
                    path,
                    display: name,
                    output: Some(out),
                });
            }
            entries
        }
        Mode::Map => map_entries
            .into_iter()
            .map(|(input, output)| Entry {
                path: PathBuf::from(&input),
                display: input,
                output: Some(output),
            })
            .collect(),
    };

    for entry in entries {
        if !process(&entry, &cfg, &mut result, &style) {
            failed = true;
        }
    }

    if let Some(path) = generate {
        let json = serde_json::to_string_pretty(&result)
            .unwrap_or_else(|e| fail(&style, &e.to_string()));
        if let Err(e) = fs::write(path, json.as_bytes()) {
            fail(&style, &e.to_string());
        }
    }

    if !cfg.quiet && !result.is_empty() {
        let rows: Vec<(String, String)> = result
            .iter()
            .map(|(k, v)| (v.clone(), k.clone()))
            .collect();
        let out = table::render(["Input", "Output"], &rows);
        let mut stdout = std::io::stdout();
        let _ = stdout.write_all(out.as_bytes());
        let _ = stdout.flush();
    }

    exit(if failed { 1 } else { 0 });
}

fn fail(style: &term::Style, message: &str) -> ! {
    term::print_error(style, message);
    exit(1);
}

fn missing_source_message(style: &term::Style) -> String {
    let mut msg = String::from("one of ");
    let names = ["regex", "sort", "map"];
    for (i, name) in names.iter().enumerate() {
        msg.push('\'');
        msg.push_str(&style.cyan(name));
        msg.push('\'');
        msg.push_str(if i + 1 == names.len() { " or " } else { ", " });
    }
    msg.push('\'');
    msg.push_str(&style.cyan("SOURCE"));
    msg.push_str("' options must be set.\n");
    msg.push_str(&style.yellow_bold("usage"));
    msg.push_str(": run '");
    msg.push_str(&style.cyan(&program_name()));
    msg.push(' ');
    msg.push_str(&style.cyan("--help"));
    msg.push_str("' for more information.");
    msg
}

fn program_name() -> String {
    env::args_os()
        .next()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_default()
}

fn extension(path: &Path) -> String {
    match path.extension() {
        Some(e) => format!(".{}", e.to_string_lossy()),
        None => String::new(),
    }
}

/// Recursively collects every entry below `dir`. The directory itself is stored
/// first, followed by its children in directory order.
fn walk(dir: &Path, rel: &Path, level: usize, min: usize, max: usize, out: &mut Vec<PathBuf>) {
    if level >= min && level <= max {
        out.push(rel.to_path_buf());
    }
    if level >= max {
        return;
    }
    let rd = match fs::read_dir(dir) {
        Ok(rd) => rd,
        Err(_) => return,
    };
    for entry in rd.flatten() {
        let child = rel.join(entry.file_name());
        walk(&entry.path(), &child, level + 1, min, max, out);
    }
}

fn process(
    entry: &Entry,
    cfg: &Config,
    result: &mut BTreeMap<String, String>,
    style: &term::Style,
    output: String,
) -> bool {
    let mut output = output;
    if !cfg.overwrite {
        loop {
            let exists = Path::new(&output).exists();
            if !exists || output == entry.display {
                break;
            }
            output = prepend_underscore(&output);
        }
    }
    if cfg.mkdir {
        if let Some(parent) = Path::new(&output).parent() {
            let _ = fs::create_dir_all(parent);
        }
    }
