use std::env;
use std::fs;
use std::path::PathBuf;

pub const SGR0: usize = 39;
pub const SETAF: usize = 359;

pub struct TermInfo {
    strings: Vec<Option<String>>,
}

impl TermInfo {
    pub fn from_env() -> Option<TermInfo> {
        let term = env::var("TERM").ok()?;
        Self::from_name(&term)
    }

    pub fn from_name(name: &str) -> Option<TermInfo> {
        let path = db_path(name)?;
        let data = fs::read(path).ok()?;
        Self::parse(&data)
    }

    pub fn get(&self, index: usize) -> Option<&str> {
        self.strings.get(index).and_then(|s| s.as_deref())
    }

    /// Value of the `setaf` capability for the given color.
    pub fn setaf(&self, color: i32) -> Option<String> {
        let cap = self.get(SETAF)?;
        Some(expand(cap, &[color]))
    }

    /// Value of the `sgr0` capability.
    pub fn sgr0(&self) -> Option<String> {
        let cap = self.get(SGR0)?;
        Some(expand(cap, &[]))
    }

    fn parse(data: &[u8]) -> Option<TermInfo> {
        if data.len() < 12 {
            return None;
        }
        let magic = u16::from_le_bytes([data[0], data[1]]);
        let extended = magic == 0o1036;
        if magic != 0o432 && !extended {
            return None;
        }
        let rd_i16 = |o: usize| -> i16 { i16::from_le_bytes([data[o], data[o + 1]]) };
        let names_len = rd_i16(2) as usize;
        let bools_len = rd_i16(4) as usize;
        let nums_count = rd_i16(6) as usize;
        let strs_count = rd_i16(8) as usize;
        let table_len = rd_i16(10) as usize;

        let mut off = 12;
        off += names_len;
        off += bools_len;
        if off % 2 == 1 {
            off += 1;
        }
        let num_size = if extended { 4 } else { 2 };
        off += num_size * nums_count;

        let mut strings = Vec::with_capacity(strs_count);
        let table_start = off + 2 * strs_count;
        for i in 0..strs_count {
            let o = rd_i16(off + 2 * i);
            if o < 0 {
                strings.push(None);
                continue;
            }
            let start = table_start + o as usize;
            if start >= table_start + table_len || start >= data.len() {
                strings.push(None);
                continue;
            }
            let end = match data[start..table_start + table_len.min(data.len())]
                .iter()
                .position(|&b| b == 0)
            {
                Some(p) => start + p,
                None => continue,
            };
            strings.push(Some(String::from_utf8_lossy(&data[start..end]).into_owned()));
        }
        Some(TermInfo { strings })
    }
}

fn db_path(name: &str) -> Option<PathBuf> {
    if name.is_empty() {
        return None;
    }
    let first = name.chars().next().unwrap();
    let mut dirs: Vec<PathBuf> = Vec::new();
    if let Some(d) = env::var_os("TERMINFO") {
        dirs.push(PathBuf::from(d));
    }
    if let Some(home) = env::var_os("HOME") {
        let mut p = PathBuf::from(home);
        p.push(".terminfo");
        dirs.push(p);
    }
    if let Some(d) = env::var_os("TERMINFO_DIRS") {
        for part in d.to_string_lossy().split(':') {
            if part.is_empty() {
                dirs.push(PathBuf::from("/usr/share/terminfo"));
            } else {
                dirs.push(PathBuf::from(part));
            }
        }
    }
    dirs.push(PathBuf::from("/etc/terminfo"));
    dirs.push(PathBuf::from("/lib/terminfo"));
    dirs.push(PathBuf::from("/usr/share/terminfo"));

    for mut p in dirs {
        if !p.exists() {
            continue;
        }
        p.push(name);
        if p.exists() {
            return Some(p);
        }
        p.pop();
        p.push(first.to_string());
        p.push(name);
        if p.exists() {
            return Some(p);
        }
    }
    None
}

/// Minimal terminfo parameterized string expansion.
pub fn expand(cap: &str, params: &[i32]) -> String {
    let chars: Vec<char> = cap.chars().collect();
    let mut i = 0usize;
    let mut stack: Vec<i32> = Vec::new();
    let mut vars: [i32; 26] = [0; 26];
    let mut out = String::new();

    while i < chars.len() {
        let c = chars[i];
        if c != '%' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i >= chars.len() {
            break;
        }
        let op = chars[i];
        i += 1;
        match op {
            '%' => out.push('%'),
            'p' => {
                if i < chars.len() {
                    let n = chars[i];
                    i += 1;
                    if let Some(d) = n.to_digit(10) {
                        if d >= 1 {
                            stack.push(params.get(d as usize - 1).copied().unwrap_or(0));
                        }
                    }
                }
            }
            'P' => {
                if i < chars.len() {
                    let n = chars[i];
                    i += 1;
                    if let Some(v) = stack.pop() {
                        if n.is_ascii_lowercase() {
                            let idx = (n as u8 - b'a') as usize;
                            vars[idx] = v;
                        }
                    }
                }
            }
            'g' => {
                if i < chars.len() {
                    let n = chars[i];
                    i += 1;
                    if n.is_ascii_lowercase() {
                        let idx = (n as u8 - b'a') as usize;
                        stack.push(vars[idx]);
                    }
                }
            }
            '\'' => {
                if i < chars.len() {
                    let ch = chars[i];
                    i += 1;
                    if i < chars.len() && chars[i] == '\'' {
                        i += 1;
                    }
                    stack.push(ch as i32);
                }
            }
            '{' => {
                let mut num = String::new();
                while i < chars.len() && chars[i] != '}' {
                    num.push(chars[i]);
                    i += 1;
                }
                if i < chars.len() {
                    i += 1;
                }
                stack.push(num.parse::<i32>().unwrap_or(0));
            }
            'l' => {
                if let Some(v) = stack.pop() {
                    stack.push(v.to_string().len() as i32);
                }
            }
            '+' | '-' | '*' | '/' | 'm' => {
                let y = stack.pop().unwrap_or(0);
                let x = stack.pop().unwrap_or(0);
                let r = match op {
                    '+' => x.wrapping_add(y),
                    '-' => x.wrapping_sub(y),
