{"command": "cd /tmp/nom && python3 - <<'PY'
p='src/terminfo.rs'
s=open(p).read()
start = s.index('/// Minimal terminfo parameterized string expansion.')
end = s.index('/// Removes padding/delay specifications')
new = '''/// Minimal terminfo parameterized string expansion.
pub fn expand(cap: &str, params: &[i32]) -> String {
    let chars: Vec<char> = cap.chars().collect();
    let mut interp = Interp {
        stack: Vec::new(),
        vars: [0; 26],
        out: String::new(),
        params: params.to_vec(),
    };
    let mut i = 0usize;
    run(&chars, &mut i, chars.len(), &mut interp);
    interp.out
}

struct Interp {
    stack: Vec<i32>,
    vars: [i32; 26],
    out: String,
    params: Vec<i32>,
}

fn find_token(chars: &[char], mut i: usize, end: usize) -> Option<(usize, char)> {
    let mut depth = 0i32;
    while i + 1 < end {
        if chars[i] == '%' {
            let t = chars[i + 1];
            if t == 't' {
                depth += 1;
            } else if t == ';' {
                if depth == 0 {
                    return Some((i, t));
                }
                depth -= 1;
            } else if depth == 0 && (t == 'e') {
                return Some((i, t));
            }
        }
        i += 1;
    }
    None
}

fn run(chars: &[char], i: &mut usize, end: usize, st: &mut Interp) {
    while *i < end {
        let c = chars[*i];
        if c != '%' {
            st.out.push(c);
            *i += 1;
            continue;
        }
        *i += 1;
        if *i >= end {
            break;
        }
        let op = chars[*i];
        *i += 1;
        match op {
            '%' => st.out.push('%'),
            'p' => {
                if *i < end {
                    let n = chars[*i];
                    *i += 1;
                    if let Some(d) = n.to_digit(10) {
                        if d >= 1 {
                            st.stack
                                .push(st.params.get(d as usize - 1).copied().unwrap_or(0));
                        }
                    }
                }
            }
            'P' => {
                if *i < end {
                    let n = chars[*i];
                    *i += 1;
                    if let Some(v) = st.stack.pop() {
                        if n.is_ascii_lowercase() {
                            let idx = (n as u8 - b'a') as usize;
                            st.vars[idx] = v;
                        }
                    }
                }
            }
            'g' => {
                if *i < end {
                    let n = chars[*i];
                    *i += 1;
                    if n.is_ascii_lowercase() {
                        let idx = (n as u8 - b'a') as usize;
                        let v = st.vars[idx];
                        st.stack.push(v);
                    }
                }
            }
            '\\'' => {
                if *i < end {
                    let ch = chars[*i];
                    *i += 1;
                    if *i < end && chars[*i] == '\\'' {
                        *i += 1;
                    }
                    st.stack.push(ch as i32);
                }
            }
            '{' => {
                let mut num = String::new();
                while *i < end && chars[*i] != '}' {
                    num.push(chars[*i]);
                    *i += 1;
                }
                if *i < end {
                    *i += 1;
                }
                st.stack.push(num.parse::<i32>().unwrap_or(0));
            }
            'l' => {
                if let Some(v) = st.stack.pop() {
                    let len = v.to_string().len() as i32;
                    st.stack.push(len);
                }
            }
            '+' | '-' | '*' | '/' | 'm' | '&' | '|' | '^' | '=' | '>' | '<' | 'A' | 'O' => {
                let y = st.stack.pop().unwrap_or(0);
                let x = st.stack.pop().unwrap_or(0);
                let r = match op {
                    '+' => x.wrapping_add(y),
                    '-' => x.wrapping_sub(y),
                    '*' => x.wrapping_mul(y),
                    '/' => {
                        if y == 0 {
                            0
                        } else {
                            x / y
                        }
                    }
                    'm' => {
                        if y == 0 {
                            0
                        } else {
                            x % y
                        }
                    }
                    '&' => x & y,
                    '|' => x | y,
                    '^' => x ^ y,
                    '=' => (x == y) as i32,
                    '>' => (x > y) as i32,
                    '<' => (x < y) as i32,
                    'A' => ((x != 0) && (y != 0)) as i32,
                    _ => ((x != 0) || (y != 0)) as i32,
                };
                st.stack.push(r);
            }
            '!' => {
                let x = st.stack.pop().unwrap_or(0);
                st.stack.push((x == 0) as i32);
            }
            '~' => {
                let x = st.stack.pop().unwrap_or(0);
                st.stack.push(!x);
            }
            'i' => {
                if st.params.len() >= 1 {
