                    let mut sub = Interp {
                        stack: st.stack.clone(),
                        vars: st.vars,
                        out: String::new(),
                        params: st.params.clone(),
                    };
                    let cc: Vec<char> = cond.chars().collect();
                    let mut j = 0usize;
                    run(&cc, &mut j, cc.len(), &mut sub);
                    sub.stack.last().copied().unwrap_or(0) != 0
                };
                // then part
                let then_start = *i;
                let tok = find_token(chars, *i, end);
                let (then_end, then_tok) = match tok {
                    Some((p, t)) => (p, t),
                    None => (end, ' '),
                };
