            let start = table_start + o as usize;
            if start >= table_end {
                strings.push(None);
                continue;
            }
            let end = match data[start..table_end].iter().position(|&b| b == 0) {
                Some(p) => start + p,
                None => return None,
            };
            strings.push(Some(String::from_utf8_lossy(&data[start..end]).into_owned()));
        }
        Some(TermInfo { strings })
    }
}

